/**
 * @file citationValidation.service.js
 * @description Validates, resolves, and evaluates source citations and claim-level evidence
 * generated by the LLM against trusted chunk metadata.
 *
 * Guarantees:
 * 1. Every source ID in the final answer maps strictly to a retrieved chunk.
 * 2. Every displayed page number comes strictly from trusted chunk metadata (rejects LLM-invented pages).
 * 3. Enforces multi-tenant ownership: citations belong strictly to the authorized user/conversation context.
 * 4. Verifies claim-level evidence alignment: does the chunk actually substantiate the claim?
 * 5. Meaningful EVIDENCE_STATUS definitions (SUPPORTED, PARTIALLY_SUPPORTED, INSUFFICIENT_EVIDENCE, CONFLICTING_EVIDENCE).
 * 6. Converts internal [S1] tags to user-facing [1] markers and outputs structured citation records.
 */

import {
    extractClaimsWithSources,
    evaluateClaimAgainstSources,
    verifyClaimsWithLLM,
    CLAIM_STATUS,
} from "./claimVerification.service.js";

export const EVIDENCE_STATUS = {
    SUPPORTED: "SUPPORTED",
    PARTIALLY_SUPPORTED: "PARTIALLY_SUPPORTED",
    INSUFFICIENT_EVIDENCE: "INSUFFICIENT_EVIDENCE",
    CONFLICTING_EVIDENCE: "CONFLICTING_EVIDENCE",
};

export const CONFIDENCE_LEVELS = {
    HIGH: "HIGH",
    MEDIUM: "MEDIUM",
    LOW: "LOW",
};

/**
 * Extracts raw source IDs from text (matches [S1], [S2], [S1, S2], [S1][S2], [Source S1]).
 *
 * @param {string} text - Raw LLM response
 * @returns {Array<string>} Array of normalized source IDs (e.g. ["S1", "S2"])
 */
export const extractSourceIds = (text = "") => {
    if (!text || typeof text !== "string") return [];
    const sourceIds = [];

    // Match patterns like [S1], [S2], [S1, S2], [S1][S2], [Source S1], [Source: S2]
    const bracketRegex = /\[(?:Source:?\s*)?([S\d,\s]+)\]/gi;
    let match;
    while ((match = bracketRegex.exec(text)) !== null) {
        const inner = match[1];
        const ids = inner.match(/S\d+/gi) || [];
        for (const id of ids) {
            const upper = id.toUpperCase();
            if (!sourceIds.includes(upper)) {
                sourceIds.push(upper);
            }
        }
    }

    return sourceIds;
};

/**
 * Checks whether a chunk contains semantic evidence for the given question or response.
 * Maintained for backward compatibility, enhanced with claim alignment.
 *
 * @param {string} chunkContent - Text of the chunk
 * @param {string} query - User question or claim text
 * @returns {boolean} True if semantic evidence overlap is detected
 */
export const hasSemanticEvidence = (chunkContent = "", query = "") => {
    if (!chunkContent) return false;
    if (!query || typeof query !== "string" || !query.trim()) return true;
    const lowerContent = chunkContent.toLowerCase();
    const queryTokens = query
        .toLowerCase()
        .replace(/[^\w\s]/g, "")
        .split(/\s+/)
        .filter((t) => t.length > 2);

    if (queryTokens.length === 0) return true;

    let matchCount = 0;
    for (const token of queryTokens) {
        if (lowerContent.includes(token)) {
            matchCount++;
        }
    }

    return matchCount > 0;
};

/**
 * Core validation and evidence assessment function.
 *
 * @param {object} params - Validation parameters
 * @param {string} params.rawText - Text output from LLM
 * @param {Map<string, object>} params.sourceMap - Grounded context source map
 * @param {string} [params.query=""] - Original user question
 * @param {string} [params.userId=""] - Authenticated user ID for ownership check
 * @param {string} [params.conversationId=""] - Conversation ID for ownership check
 * @param {string} [params.targetDocumentId=""] - Targeted document ID
 * @param {Array<object>} [params.precomputedEvaluations=null] - Optional precomputed claim evaluations (e.g. from LLM verifier)
 * @returns {{
 *   answer: string,
 *   citations: Array<object>,
 *   evidenceStatus: string,
 *   confidence: string,
 *   claims: Array<object>,
 *   unsupportedClaims: Array<object>,
 *   validSourceCount: number,
 *   invalidSourceCount: number,
 *   hasCitations: boolean
 * }}
 */
export const validateAnswerCitations = (params = {}, maybeSourceMap = null, maybeQuery = "") => {
    let rawText = "";
    let sourceMap = new Map();
    let query = "";
    let userId = "";
    let conversationId = "";
    let targetDocumentId = "";
    let precomputedEvaluations = null;

    if (typeof params === "string") {
        rawText = params;
        sourceMap = maybeSourceMap instanceof Map ? maybeSourceMap : new Map();
        query = typeof maybeQuery === "string" ? maybeQuery : "";
    } else if (params && typeof params === "object") {
        rawText = params.rawText || "";
        sourceMap = params.sourceMap || new Map();
        query = params.query || "";
        userId = params.userId || "";
        conversationId = params.conversationId || "";
        targetDocumentId = params.targetDocumentId || "";
        precomputedEvaluations = params.precomputedEvaluations || null;
    }

    if (!rawText || typeof rawText !== "string") {
        return {
            answer: "",
            citations: [],
            evidenceStatus: EVIDENCE_STATUS.INSUFFICIENT_EVIDENCE,
            confidence: CONFIDENCE_LEVELS.LOW,
            claims: [],
            unsupportedClaims: [],
            validSourceCount: 0,
            invalidSourceCount: 0,
            hasCitations: false,
        };
    }

    // 1. Detect explicit statements of insufficiency or inability to find data
    const lowerText = rawText.toLowerCase();
    const isInsufficient =
        lowerText.includes("could not find") ||
        lowerText.includes("does not contain") ||
        lowerText.includes("no information") ||
        lowerText.includes("insufficient evidence") ||
        lowerText.includes("not mentioned in the document");

    const isExplicitConflicting =
        lowerText.includes("conflict") ||
        lowerText.includes("discrepancy") ||
        lowerText.includes("contradicts");

    // 2. Extract Claims and Evaluate Claim-Level Evidence
    const claims = extractClaimsWithSources(rawText);
    const claimEvaluations = precomputedEvaluations || claims.map((c) => {
        const evalRes = evaluateClaimAgainstSources(c, sourceMap);
        return {
            claimIndex: c.claimIndex,
            text: c.text,
            rawSegment: c.rawSegment,
            sourceIds: c.sourceIds,
            status: evalRes.status,
            confidence: evalRes.confidence,
            verifiedSources: evalRes.verifiedSources,
            unverifiedSources: evalRes.unverifiedSources,
            reason: evalRes.reason,
        };
    });

    const supportedClaims = claimEvaluations.filter((c) => c.status === CLAIM_STATUS.SUPPORTED);
    const unsupportedClaims = claimEvaluations.filter((c) => c.status === CLAIM_STATUS.UNSUPPORTED);
    const conflictingClaims = claimEvaluations.filter((c) => c.status === CLAIM_STATUS.CONFLICTING);

    // 3. Extract and Verify All Cited Source IDs
    const citedSourceIds = extractSourceIds(rawText);
    const validCitations = [];
    const validSourceIdSet = new Set();
    let invalidSourceCount = 0;
    let citationCounter = 1;

    for (const sourceId of citedSourceIds) {
        const trustedSource = sourceMap.get(sourceId);
        if (!trustedSource) {
            // Hallucinated or non-existent source ID
            invalidSourceCount++;
            continue;
        }

        // Verify tenant ownership
        if (userId && trustedSource.userId && trustedSource.userId !== userId) {
            invalidSourceCount++;
            continue;
        }
        if (conversationId && trustedSource.conversationId && trustedSource.conversationId !== conversationId) {
            invalidSourceCount++;
            continue;
        }

        if (!validSourceIdSet.has(sourceId)) {
            validSourceIdSet.add(sourceId);
            const snippet = (trustedSource.content || "")
                .replace(/\s+/g, " ")
                .trim()
                .slice(0, 180);

            // Check if this source actually substantiated any factual claim
            const substantiatedClaim = claimEvaluations.some(
                (c) => c.verifiedSources?.includes(sourceId)
            );

            // Check semantic support against query (backward compatibility) and claim
            const semanticSupport = hasSemanticEvidence(trustedSource.content, query);

            validCitations.push({
                sourceId: trustedSource.sourceId,
                citationNumber: citationCounter++,
                documentId: trustedSource.documentId,
                documentName: trustedSource.documentName,
                chunkId: trustedSource.chunkId,
                pageStart: trustedSource.pageStart,
                pageEnd: trustedSource.pageEnd,
                section: trustedSource.section,
                snippet: snippet.length === 180 ? `${snippet}...` : snippet,
                hasSemanticSupport: substantiatedClaim || semanticSupport,
                hasClaimSupport: substantiatedClaim,
                contentType: trustedSource.contentType || "TEXT",
                extractionMethod: trustedSource.extractionMethod || "text",
                visualMetadata: trustedSource.visualMetadata || null,
            });
        }
    }

    // 4. Safe Handling of Unsupported Claims & Citation Tag Replacement
    // Replace internal [S1], [S2] tags with verified citation numbers [1], [2]
    // Remove invalid source tags (e.g. [S99])
    let formattedAnswer = rawText.replace(/\[(?:Source:?\s*)?([S\d,\s]+)\]/gi, (fullMatch, inner) => {
        const ids = inner.match(/S\d+/gi);
        if (!ids) {
            return fullMatch;
        }
        const resolvedNumbers = [];
        for (const id of ids) {
            const cit = validCitations.find((c) => c.sourceId.toUpperCase() === id.toUpperCase());
            if (cit && !resolvedNumbers.includes(cit.citationNumber)) {
                resolvedNumbers.push(cit.citationNumber);
            }
        }
        if (resolvedNumbers.length > 0) {
            return `[${resolvedNumbers.join(", ")}]`;
        }
        // Entirely invalid source tags (e.g. [S99]) are removed
        return "";
    });

    formattedAnswer = formattedAnswer.replace(/  +/g, " ").trim();

    // 5. Determine Accurate EVIDENCE_STATUS & CONFIDENCE
    let evidenceStatus = EVIDENCE_STATUS.SUPPORTED;
    let confidence = CONFIDENCE_LEVELS.HIGH;

    const hasAnyVerifiedCitation = validCitations.length > 0;
    const hasAnyClaimSupport = supportedClaims.length > 0;

    if (isExplicitConflicting || conflictingClaims.length > 0) {
        evidenceStatus = EVIDENCE_STATUS.CONFLICTING_EVIDENCE;
        confidence = CONFIDENCE_LEVELS.LOW;
    } else if (isInsufficient || !hasAnyVerifiedCitation) {
        evidenceStatus = EVIDENCE_STATUS.INSUFFICIENT_EVIDENCE;
        confidence = CONFIDENCE_LEVELS.LOW;
    } else if (supportedClaims.length > 0 && (unsupportedClaims.length > 0 || invalidSourceCount > 0)) {
        // A response with some supported claims and some unsupported claims receives PARTIALLY_SUPPORTED
        evidenceStatus = EVIDENCE_STATUS.PARTIALLY_SUPPORTED;
        confidence = CONFIDENCE_LEVELS.MEDIUM;
    } else if (invalidSourceCount > 0) {
        evidenceStatus = EVIDENCE_STATUS.PARTIALLY_SUPPORTED;
        confidence = CONFIDENCE_LEVELS.MEDIUM;
    } else if (unsupportedClaims.length > 0 && supportedClaims.length === 0) {
        // All factual claims were unsupported by the cited evidence
        evidenceStatus = EVIDENCE_STATUS.INSUFFICIENT_EVIDENCE;
        confidence = CONFIDENCE_LEVELS.LOW;
    } else if (validCitations.some((c) => !c.hasClaimSupport && !c.hasSemanticSupport)) {
        evidenceStatus = EVIDENCE_STATUS.PARTIALLY_SUPPORTED;
        confidence = CONFIDENCE_LEVELS.MEDIUM;
    } else {
        evidenceStatus = EVIDENCE_STATUS.SUPPORTED;
        confidence = CONFIDENCE_LEVELS.HIGH;
    }

    return {
        answer: formattedAnswer,
        citations: validCitations,
        evidenceStatus,
        confidence,
        claims: claimEvaluations,
        unsupportedClaims,
        validSourceCount: validCitations.length,
        invalidSourceCount,
        hasCitations: validCitations.length > 0,
    };
};

/**
 * Async validation supporting optional LLM verification.
 *
 * @param {object} params - Same as validateAnswerCitations, plus optional verifierModel
 * @param {any} [params.verifierModel] - LangChain model instance for structured verification
 * @param {number} [params.timeoutMs=3500] - Verifier timeout
 * @returns {Promise<object>} Validation results
 */
export const validateAnswerCitationsAsync = async (params = {}) => {
    const { rawText = "", sourceMap = new Map(), verifierModel = null, timeoutMs = 3500 } = params;

    let precomputedEvaluations = null;
    if (verifierModel && rawText) {
        const claims = extractClaimsWithSources(rawText);
        precomputedEvaluations = await verifyClaimsWithLLM({
            claims,
            sourceMap,
            verifierModel,
            timeoutMs,
        });
    }

    return validateAnswerCitations({
        ...params,
        precomputedEvaluations,
    });
};
